      rendered = parameters;
      return 1;
    }),
    reset: vi.fn(),
  };
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string, init?: RequestInit) => {
      if (url === "/api/form-config") return Response.json(formConfig);
      const body = JSON.parse(String(init?.body)) as Record<string, unknown>;
